package com.ruralhelp.model;

/**
 * Encapsulates an NGO match recommendation generated by the matching engine.
 */
public class MatchRecommendation implements Comparable<MatchRecommendation> {
    private NGO ngo;
    private int matchScore; // 0 to 100
    private boolean categoryMatched;
    private boolean areaMatched;
    private boolean capacityAvailable;
    private String recommendationReason;

    public MatchRecommendation(NGO ngo, int matchScore, boolean categoryMatched, 
                               boolean areaMatched, boolean capacityAvailable, String recommendationReason) {
        this.ngo = ngo;
        this.matchScore = matchScore;
        this.categoryMatched = categoryMatched;
        this.areaMatched = areaMatched;
        this.capacityAvailable = capacityAvailable;
        this.recommendationReason = recommendationReason;
    }

    public NGO getNgo() { return ngo; }
    public int getMatchScore() { return matchScore; }
    public boolean isCategoryMatched() { return categoryMatched; }
    public boolean isAreaMatched() { return areaMatched; }
    public boolean isCapacityAvailable() { return capacityAvailable; }
    public String getRecommendationReason() { return recommendationReason; }

    @Override
    public int compareTo(MatchRecommendation o) {
        // Higher scores first
        return Integer.compare(o.matchScore, this.matchScore);
    }

    @Override
    public String toString() {
        return ngo.getOrganizationName() + " (Score: " + matchScore + "%) - " + recommendationReason;
    }
}
